  ('0bc04e8d-0b7b-418d-9a26-d83a1bd2e864', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका इस स्थिति में कैसे आ फँसे? यह कौन-सी स्थिति है? इसके लिए कौन जिम्मेवार है? यह सब बताने से पहले अपने गाँव का और खासकर अपने गाँव की ठाकुरबारी का संक्षिप्त परिचय मैं आपको दे देना उचित समझता हूँ क्योंकि उसके बिना तो यह कहानी अधूरी ही रह जाएगी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ba71fbc8-0918-4e11-addf-fb4f243992b9', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा गाँव कस्बाई शहर आरा से चालीस किलोमीटर की दूरी पर है। हसनबाजार बस स्टैंड के पास। गाँव की कुल आबादी ढाई-तीन हजार होगी। गाँव में तीन प्रमुख स्थान हैं। गाँव के पश्चिम किनारे का बड़ा-सा तालाब। गाँव के मध्य स्थित बरगद का पुराना वृक्ष और गाँव के पूरब में ठाकुरजी का विशाल मंदिर, जिसे गाँव के लोग ठाकुरबारी कहते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e67cad8b-cb00-4002-b2da-82e0ce1382ac', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में इस ठाकुरबारी की स्थापना कब हुई, इसकी ठीक-ठीक जानकारी किसी को नहीं। इस संबंध में गाँव में जो कहानी प्रचलित है वह यह कि वर्षों पहले जब यह गाँव पूरी तरह बसा भी नहीं था, कहीं से एक संत आकर इस स्थान पर झोपड़ी बना रहने लगे थे। वह सुबह-शाम यहाँ ठाकुरजी की पूजा करते थे। लोगों से मांगकर खा लेते थे और पूजा-पाठ की भावना जाग्रत करते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f8329004-f203-44e3-b7fa-de40fe67ef4b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाद में लोगों ने चंदा करके यहाँ ठाकुरजी का एक छोटा-सा मंदिर बनवा दिया। फिर जैसे-जैसे गाँव बसता गया और आबादी बढ़ती गई, मंदिर के कलेवर में भी विस्तार होता गया। लोग ठाकुरजी को मन्नौती मनाते कि पुत्र हो, मुकदमे में विजय हो, लड़की की शादी अच्छे घर में तय हो, लड़के को नौकरी मिल जाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b61f8310-efa1-47f4-a225-c8d2fa5d5a86', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर इसमें जिनको सफलता मिलती, वह खुशी में ठाकुरजी पर रुपये, जेवर, अनाज चढ़ाते। अधिक खुशी होती तो ठाकुरजी के नाम अपने खेत का एक छोटा-सा टुकड़ा लिख देते। यह परंपरा आज तक जारी है। अधिकांश लोगों को विश्वास है कि उन्हें अच्छी फसल होती है तो ठाकुरजी की कृपा से। मुकदमे में उनकी जीत हुई तो ठाकुरजी के चलते। लड़की की शादी इसीलिए जल्दी तय हो गई, क्योंकि ठाकुरजी को मन्नौती मनाई गई थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('efd3b40a-5a8c-49c8-ba71-f2457d37bf41', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों के इस विश्वास का ही यह परिणाम है कि गाँव की अन्य चीज़ों की तुलना में ठाकुरबारी का विकास हजार गुना अधिक हुआ है। अब तो यह गाँव ठाकुरबारी से ही पहचाना जाता है। यह ठाकुरबारी न सिर्फ मेरे गाँव की एक बड़ी और विशाल ठाकुरबारी है बल्कि पूरे इलाके में इसकी जोड़ की दूसरी ठाकुरबारी नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6623e20b-c121-4448-a3f5-18c837f9e1f7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठाकुरबारी के नाम पर बीस बीघे खेत हैं। धार्मिक लोगों की एक समिति है, जो ठाकुरबारी की देखरेख और संचालन के लिए प्रत्येक तीन साल पर एक महंत और एक पुजारी की नियुक्ति करती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ef96d43a-27a1-4edf-ae26-d82fdd3a6030', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के बारे में मैं सोचता हूँ तो मुझे लगता है कि वह यह समझ नहीं पा रहे हैं कि कहें तो क्या कहें? अब कोई ऐसी बात नहीं जिसे कहकर वह हल्का हो सकें। कोई ऐसी उक्ति नहीं जिसे कहकर वे मुक्ति पा सकें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('aca62f9e-82c8-41d7-9d9c-4ca059aa4d5e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में तीन प्रमुख स्थान हैं। गाँव के पश्चिम किनारे का बड़ा-सा तालाब। गाँव के मध्य स्थित बरगद का पुराना वृक्ष और गाँव के पूरब में ठाकुरजी का विशाल मंदिर, जिसे गाँव के लोग ठाकुरबारी कहते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a3ee602d-19b4-4b57-9f98-9772512706dd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के परिवार के पास कुल साठ बीघे खेत हैं। प्रत्येक भाई के हिस्से पंद्रह बीघे पड़ेंगे। कृषि-कार्य पर ये लोग निर्भर हैं। शायद इसीलिए अब तक संयुक्त परिवार के रूप में ही रहते आ रहे हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('32bfba52-a1dd-4b67-bd69-e32584c2835c', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के तीनों भाइयों ने अपनी पत्नियों को यह सीख दी थी कि हरिहर काका की अच्छी तरह सेवा करें। समय पर उन्हें नाश्ता-खाना दें। किसी बात की तकलीफ न होने दें। कुछ दिनों तक वे हरिहर काका की खोज-खबर लेती रहीं। फिर उन्हें कौन पूछने वाला? 'ठहर-चौका' लगाकर पंखा झलते हुए अपने मर्दों को अच्छे-अच्छे व्यंजन खिलातीं। हरिहर काका के आगे तो बची-खुची चीजें आतीं। कभी-कभी तो हरिहर काका को रूखा-सूखा खाकर ही संतोष करना पड़ता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7cce4493-c576-44b9-b4b6-4bcf2e888877', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर कभी हरिहर काका की तबीयत खराब हो जाती तो वह मुसीबत में पड़ जाते। इतने बड़े परिवार के रहते हुए भी कोई उन्हें पानी देने वाला तक नहीं। सभी अपने कामों में मशगूल। बच्चे या तो पढ़-लिख रहे होते या धमाचौकड़ी मचाते। मर्द खेतों पर गए रहते। औरतें हाल पूछने भी नहीं आतीं। दालान के कमरे में अकेले पड़े हरिहर काका को स्वयं उठकर अपनी जरूरतों की पूर्ति करनी पड़ती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1048511e-967a-482e-9e6c-821033d5da64', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ऐसे वक्त अपनी पत्नियों को याद कर-करके हरिहर काका की आँखें भर आतीं। भाइयों के परिवार के प्रति मोहभंग की शुरुआत इन्हीं क्षणों में हुई थी। और फिर, एक दिन तो विस्फोट ही हो गया। उस दिन हरिहर काका की सहन-शक्ति जवाब दे गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2e2b6fb9-4f02-4ec2-95e2-bf9dd9788be3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस दिन शहर में क्लर्की करने वाले भतीजे का एक दोस्त गाँव आया था। उसी के आगमन के उपलक्ष्य में दो-तीन तरह की सब्जी, बजेके, चटनी, रायता आदि बने थे। बीमारी से उठे हरिहर काका का मन स्वादिष्ट भोजन के लिए बेचैन था। मन ही मन उन्होंने अपने भतीजे के दोस्त की सराहना की, जिसके बहाने उन्हें अच्छी चीजें खाने को मिलने वाली थीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('443d1441-01f6-436c-901e-886566fbd935', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन बातें बिलकुल विपरीत हुईं। सबों ने खाना खा लिया, उनको कोई पूछने तक नहीं आया। उनके तीनों भाई खाना खाकर खलिहान में चले गए। दौनी हो रही थी। वे इस बात के प्रति निश्चिंत थे कि हरिहर काका को तो पहले ही खिला दिया गया होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7d6cd6f5-76e6-418b-a610-07428141269e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंत में हरिहर काका ने स्वयं दालान के कमरे से निकल हवेली में प्रवेश किया। तब उनके छोटे भाई की पत्नी ने रूखा-सूखा खाना लाकर उनके सामने परोस दिया— भात, दाल और अचार। बस, हरिहर काका के बदन में तो जैसे आग लग गई। उन्होंने थाली उठाकर बीच आँगन में फेंक दी। झन्न की तेज आवाज के साथ आँगन में थाली गिरी। भात बिखर गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('94e20a11-978f-4086-ba54-5748cb6268e9', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विभिन्न घरों में बैठी लड़कियाँ, बहुएँ सब एक ही साथ बाहर निकल आईं। हरिहर काका गरजते हुए हवेली से दालान की ओर चल पड़े— 'समझ रही हो कि मुफ्त में खिलाती हो, तो अपने मन से यह बात निकाल देना। मेरे हिस्से के खेत की पैदावार इसी घर में आती है। उसमें तो मैं दो-चार नौकर रख लूँ, आराम से खाऊँ, तब'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f08b1ba8-d6e8-439d-b502-f26d740f773b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के परिवार के पास कुल साठ बीघे खेत हैं। प्रत्येक भाई के हिस्से पंद्रह बीघे पड़ेंगे। कृषि-कार्य पर ये लोग निर्भर हैं। शायद इसीलिए अब तक संयुक्त परिवार के रूप में ही रहते आ रहे हैं। हरिहर काका के तीनों भाइयों ने अपनी पत्नियों को यह सीख दी थी कि हरिहर काका की अच्छी तरह सेवा करें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8738b284-cdc9-4f37-954b-e4145a8d8e06', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर कभी हरिहर काका की तबीयत खराब हो जाती तो वह मुसीबत में पड़ जाते। इतने बड़े परिवार के रहते हुए भी कोई उन्हें पानी देने वाला तक नहीं। सभी अपने कामों में मशगूल। बच्चे या तो पढ़-लिख रहे होते या धमाचौकड़ी मचाते। मर्द खेतों पर गए रहते। औरतें हाल पूछने भी नहीं आतीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fd86a661-75cc-438d-a4d2-dbe0ce1eb23e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन हरिहर काका न ^हाँ* कहते और न ^ना*। ^ना* कहकर वे महंत जी को दुखी करना नहीं चाहते थे क्योंकि भाई के परिवार से जो सुख-सुविधाएँ उन्हें मिल रही थीं, वे महंत जी की कृपा से ही। और ^हाँ* तो उन्हें कहना है नहीं, क्योंकि अपनी जिंदगी में अपनी जमीन उन्हें किसी को नहीं लिखनी। इस मुद्दे पर वे जागरूक हो गए थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('12ab1437-ae1d-4026-94ab-51cb08de30a8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर बीतते समय के अनुसार महंत जी की चिंताएँ बढ़ती जा रही थीं। जाल में फँसी चिड़िया पकड़ से बाहर हो गई थी, महंत जी इस बात को सह नहीं पा रहे थे। महंत जी को लग रहा था कि हरिहर धर्म-संकट में पड़ गया है। एक ओर वह चाहता है कि ठाकुरजी को लिख दूँ, किंतु दूसरी ओर भाई के परिवार के माया-मोह में बँध जाता है। इस स्थिति में हरिहर का अपहरण कर ”जबरदस्ती उससे लिखवाने के अतिरिक्त दूसरा कोई विकल्प नहीं। बाद में हरिहर स्वयं राजी हो जाएगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9ebb3dac-bb7f-4e27-8930-d287eeae0357', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महंत जी लड़ाकू और दबंग प्रकृति के आदमी हैं। अपनी योजना को कार्य-रूप में परिणत करने के लिए वह जी-जान से जुट गए। हालाँकि यह सब गोपनीयता का निर्वाह करते हुए ही वह कर रहे थे। हरिहर काका के भाइयों को इसकी भनक तक नहीं थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('162ba15b-b25c-4af1-b291-6a9940d9101f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात अभी हाल की ही है। आधी रात के आसपास ठाकुरबारी के साधु-संत और उनके पक्षधर भाला, गँडासा और बंदूक से लैस एकाएक हरिहर काका के दालान पर आ धमके। हरिहर काका के भाई इस अप्रत्याशित हमले के लिए तैयार नहीं थे। इससे पहले कि वे जवाबी कार्रवाई करें और गुहार लगाकर अपने लोगों को जुटाएँ, तब तक आक्रमणकारी उनको पीठ पर लादकर चंपत हो गए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca6bc446-47bd-47e4-9a23-2c416ee1f77b', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में किसी ने ऐसी घटना नहीं देखी थी, न सुनी ही थी। सारा गाँव जाग गया। शुभचिंतक तो उनके यहाँ जुटने लगे, लेकिन अन्य लोग अपने दालान और मकान की छतों पर जमा होकर आहट लेने और बातचीत करने लगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7b0f8f2d-b527-4a06-9666-40255b5246c2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के भाई लोगों के साथ उन्हें ढूँढ़ने निकले। उन्हें लगा कि यह महंत का काम है। वे मय दल-बल ठाकुरबारी जा पहुँचे। वहाँ खामोशी और शांति नजर आई। रोज की भाँति ठाकुरबारी का मुख्य फाटक बंद था। वातावरण में रात का सन्नाटा और सूनापन व्याप्त मिला।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2fa49a74-9f29-4593-b2ad-35f8ce170ab6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्हें लगा, यह काम महंत का नहीं, बाहर के डाकुओं का है। वे तो हरजाने की मोटी रकम लेकर ही हरिहर काका को मुक्त करेंगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5294212d-7101-4a8e-8c46-f9d658409d18', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खोज में निकले लोग किसी दूसरी दिशा की ओर प्रस्थान करते कि इसी समय ठाकुरबारी के अंदर से बातचीत करने की सम्मिलित, किंतु धीमी आवाज सुनाई पड़ी। सबके कान खड़े हो गए। उन्हें यकीन हो गया कि हरिहर काका इसी में हैं। अब क्या सोचना? वे ठाकुरबारी का फाटक पीटने लगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('240b22c2-7d78-418c-a5ca-bf08c5639444', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका न ^हाँ* कहते और न ^ना*। ^ना* कहकर वे महंत जी को दुखी करना नहीं चाहते थे क्योंकि भाई के परिवार से जो सुख-सुविधाएँ उन्हें मिल रही थीं, वे महंत जी की कृपा से ही। और ^हाँ* तो उन्हें कहना है नहीं, क्योंकि अपनी जिंदगी में अपनी जमीन उन्हें किसी को नहीं लिखनी। इस मुद्दे पर वे जागरूक हो गए थे। पर बीतते समय के अनुसार महंत जी की चिंताएँ बढ़ती जा रही थीं। जाल में फँसी चिड़िया पकड़ से बाहर हो गई थी, महंत जी इस बात को सह नहीं पा रहे थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7b2ec6fb-7c45-4a77-9231-f2155875c332', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महंत जी लड़ाकू और दबंग प्रकृति के आदमी हैं। अपनी योजना को कार्य-रूप में परिणत करने के लिए वह जी-जान से जुट गए। हालाँकि यह सब गोपनीयता का निर्वाह करते हुए ही वह कर रहे थे। हरिहर काका के भाइयों को इसकी भनक तक नहीं थी। बात अभी हाल की ही है। आधी रात के आसपास ठाकुरबारी के साधु-संत और उनके पक्षधर भाला, गँडासा और बंदूक से लैस एकाएक हरिहर काका के दालान पर आ धमके।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('99008f20-48f9-4cf6-8a2a-9254fc4b4810', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस वर्ग की ओर से हवाई फायरिंग भी किए जा रहे थे, लेकिन ठाकुरबाड़ी की ओर से कोई जवाब नहीं आ रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('dfa463dc-89ab-4412-873e-177036dac6fe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुबह तड़के एक वृद्ध साधु ने ठाकुरबाड़ी का फाटक खोल दिया। उस साधु की उम्र अस्सी वर्ष से अधिक की होगी। वह लाठी के सहारे काँपते हुए खड़ा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3c94a907-d53b-4df0-ada2-5db46a76180d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज ने उस वृद्ध साधु के पास पहुँच हरिहर काका तथा ठाकुरबाड़ी के महंत, पुजारी एवं अन्य साधुओं के बारे में पूछा। लेकिन उसने कुछ भी बताने से इनकार कर दिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f5401dee-949a-4975-8e20-bd88a67c86ab', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज ने कई बार उससे पूछा। डाँट लगाई, धमकियाँ दीं, लेकिन हर बार एक ही वाक्य कहता, 'मुझे कुछ मालूम नहीं।' ऐसे वक्त पुलिस के लोग मार-पीट का सहारा लेकर भी बात उगलवाते हैं; लेकिन उस साधु की वय देखकर पुलिस इंचार्ज को महटिया जाना पड़ा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('41bf94c0-3eb2-4b36-abd2-646ebb65b678', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज के नेतृत्व में पुलिस के जवान ठाकुरबाड़ी की तलाशी लेने लगे। लेकिन न तो ठाकुरबाड़ी के नीचे के कमरों में ही कोई पाया गया और न छत के कमरों में ही।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('9ad0272d-fb30-4cf4-9fe7-04aa580b078d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के जवानों ने खूब छान-बीन की, उस वृद्ध साधु के अलावा कोई दूसरा ठाकुरबाड़ी में नहीं मिला।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('8b635d9c-1ce5-497c-a037-f6f108a951c1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के भाई चिंता, परेशानी और दुखद आश्चर्य से घिर गए। ठाकुरबाड़ी के महंत और साधु-संत हरिहर काका को लेकर कहाँ भाग गए? अब क्या होगा?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f3b514a1-628e-45a5-8c1a-5e7e6e0b8ac9', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$काफी पैसे खर्च कर पुलिस को लाए थे। पुलिस के साथ आने के बाद वह अंदर ही अंदर गर्व महसूस कर रहे थे। उन्हें लग रहा था कि अब भाई को वे आसानी से घर ले जाएंगे तथा साधु-संतों को जेल भिजवा देंगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('4d8c5117-34de-4bb6-a941-5aaeba0655ca', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन दोनों में से एक भी नहीं हुआ। ठाकुरबाड़ी के जो कमरे खुले थे, उनकी तलाशी पहले ली गई थी। बाद में जिन कमरों की चिटकिनी बंद थी, उन्हें भी खोलकर देखा गया था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('21ec904b-2669-4ad5-9fa5-241769d8c1cb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक कमरे के बाहर बड़ा-सा ताला लटक रहा था। पुलिस और हरिहर काका के भाई सब वहीं एकत्र हो गए। उस कमरे की कुंजी की माँग वृद्ध साधु से की गई तो उसने साफ कह दिया, 'मेरे पास नहीं।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ea3aef38-e0fa-48e4-a88f-e949ac28dd8d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब उससे पूछा गया, 'इस कमरे में क्या है?' तब उसने जवाब दिया, 'अनाज है।' पुलिस इंचार्ज अभी यह सोच ही रहे थे कि इस कमरे का ताला तोड़कर देखा जाए या छोड़ दिया जाए कि अचानक उस कमरे के दरवाजे को भीतर से किसी ने धक्का देना शुरू किया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('29043cd9-931e-4d97-b573-12acc954b1f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के जवान सावधान हो गए। ताला तोड़कर कमरे का दरवाजा खोला गया। कमरे के भीतर हरिहर काका जिस स्थिति में मिले, उसे देखकर उनके भाइयों का खून खौल उठा। उस वक्त अगर महंत, पुजारी या अन्य नौजवान साधु उन्हें नजर आ जाते तो वे जीते-जी उन्हें नहीं छोड़ते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e6ce5efe-7697-4612-bbd2-aa55581ff779', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन हरिहर काका सोच कुछ और रहे थे और वातावरण कुछ दूसरा ही तैयार हो रहा था। ठाकुरबारी से जिस दिन उन्हें वापस लाया गया था, उसी दिन से उनके भाई और रिश्ते-नाते के लोग समझाने लगे थे कि विधिवत अपनी जायदाद वे अपने भतीजों के नाम लिख दें। वह जब तक ऐसा नहीं करेंगे तब तक महंत की गिद्ध-दृष्टि उनके ऊपर लगी रहेगी। सिर पर मंडरा रहे तूफान से मुक्ति पाने के लिए उनके समक्ष अब यही एकमात्र रास्ता है---।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('45d42c0c-38c1-454f-b667-dbbb9b86fdbe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुबह, दोपहर, शाम, रात गए तक यही चर्चा। लेकिन हरिहर काका साफ नकार जाते। कहते—'मेरे बाद तो मेरी जायदाद इस परिवार को स्वतः मिल जाएगी इसलिए लिखने का कोई अर्थ नहीं। महंत ने अँगूठे के जो जबरन निशान लिए हैं, उसके खिलाफ मुकदमा हमने किया ही है---।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('97f8cb58-c003-477c-84b1-2a1838d240b4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भाई जब समझाते-समझाते हार गए तब उन्होंने डाँटना और दबाव देना शुरू किया। लेकिन काका इस रास्ते भी राजी नहीं हुए। स्पष्ट कह दिया कि अपनी जिंदगी में वह नहीं लिखेंगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6546dcc6-ea4d-42e8-9983-07840decddc4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बस, एक रात उनके भाइयों ने वही रूप धारण कर लिया, जो रूप महंत और उनके सहयोगियों ने धारण किया था। हरिहर काका को अपनी आँखों पर विश्वास नहीं हुआ। उनके वही अपने सगे भाई, जो उनकी सेवा और सुरक्षा में तैयार रहते थे, उन्हें अपना अभिन्न समझते थे, जो उनकी नींद ही सोते और जागते थे, हथियार लेकर उनके सामने खड़े थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('719d2db4-5c7b-4377-9bb2-91ff1937fa22', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कह रहे थे—'सीधे मन से कागजों पर जहाँ-जहाँ जरूरत है, अँगूठे के निशान बनाते चलो अन्यथा मारकर यहीं घर के अंदर गाड़ देंगे। गाँव के लोगों को कोई सूचना तक नहीं मिल पाएगी।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1ff9f3cf-a7be-4de7-99a0-8523aba3b32d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर पहले वाली बात होती तो हरिहर काका डर जाते। अज्ञान की स्थिति में ही मनुष्य मृत्यु से डरते हैं। ज्ञान होने के बाद तो आदमी आवश्यकता पड़ने पर मृत्यु को वरण करने के लिए तैयार हो जाता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('78f7bee9-ff7a-46d2-a1eb-28043127d511', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका ने सोच लिया कि ये सब एक ही बार उन्हें मार दें, वह ठीक होगा; लेकिन अपनी जमीन लिखकर रामेश्वर की विधवा की तरह शेष जिंदगी वे घुट-घुटकर मरें, यह ठीक नहीं होगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6f8ca757-18ae-45e3-b4d1-4ba0c37e2d14', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रामेश्वर की विधवा को बहला-फुसलाकर उसके हिस्से की जमीन रामेश्वर के भाइयों ने लिखवा ली। शुरू में तो उसका खूब आदर-मान किया, लेकिन बुढ़ापे में उसे दोनों जून खाना देते उन्हें अखरने लगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9c0cc147-56cd-4b0d-a63b-f0e801de8c9f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंत में तो उसकी वह दुर्गति हुई कि गाँव के लोग देखकर सिहर जाते। हरिहर काका को लगता है कि अगर रामेश्वर की विधवा ने अपनी जमीन नहीं लिखी होती तो अंत समय तक लोग उसके पाँव पखारते होते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dae30f60-b492-4865-a32e-fa619c50e3d7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका गुस्से में खड़े हो गए और गरजते हुए कहा, 'मैं अकेला हूँ---तुम सब इतने हो! ठीक है, मुझे मार दो---मैं मर जाऊँगा, लेकिन जीते-जी एक धूर जमीन भी तुम्हें नहीं लिखूँगा---'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2e74597c-ed8d-433b-b6eb-0d064e3bd375', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$---तुम सब ठाकुरबारी के महंत-पुजारी से रत्ती भर भी कम नहीं---!'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('264b19bd-bb54-4718-b7f3-e38298b93e46', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'देखते हैं, कैसे नहीं लिखोगे? लिखना तो तुम्हें है ही, चाहे हँस के लिखो या रो के---।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2dff7b50-128a-4587-9c79-f12ebebb81ec', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब उसी स्थिति में रहकर ही उनके भाइयों और महंत जी ने पैरवी लगा और पैसे खर्च कर उन्हें पूरी सहायता पहुँचाई। यह उनकी सहायता का ही परिणाम गहै कि एक व्यक्ति की सुरक्षा के लिए गाँव में पुलिस के चार जवान तैनात कर दिए गए हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('24a176e3-b440-4431-bfef-c8082ec6a7ea', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जहाँ तक मैं समझता हूँ, फिलहाल हरिहर काका पुलिस की सुरक्षा में रह ज़रूर रहे हैं, लेकिन वास्तविक सुरक्षा ठाकुरबारी और अपने भाइयों की ओर से ही मिल रही है। ठाकुरबारी के साधु-संत और काका के भाई इस बात के प्रति पूरी तरह सतर्क हैं कि उनमें से कोई या गाँव का कोई अन्य हरिहर काका के साथ ज़ोर-ज़बरदस्ती न करने पाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b9b077e5-4bc9-4567-9925-3061b2a682c4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$साथ ही अपना सद्भाव और मधुर व्यवहार प्रकट कर पुनः उनका ध्यान अपनी ओर खींच लेने के लिए दोनों दल प्रयत्नशील हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b0d8158e-4dfb-4f2c-8a0c-6c152d0d5b3e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में एक नेता जी हैं, वह न तो कोई नौकरी करते हैं और न खेती-गृहस्थी, फिर भी बारह महीने मौज़ उड़ाते रहते हैं। राजनीति की जादुई छड़ी उनके पास है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
