  ('4b8ed90b-f71d-4c67-895b-b8f8e8e2b0f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के यहाँ से मैं अभी-अभी लौटा हूँ। कल भी उनके यहाँ गया था, लेकिन न तो वह कल ही कुछ कह सके और न आज ही। दोनों दिन उनके पास मैं देर तक बैठा रहा, लेकिन उन्होंने कोई बातचीत नहीं की।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('098bd73f-6935-4f7a-9002-831015a823a5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब उनकी तबीयत के बारे में पूछा तब उन्होंने सिर उठाकर एक बार मुझे देखा। फिर सिर झुकाया तो दुबारा मेरी ओर नहीं देखा। हालाँकि उनकी एक ही नज़र बहुत कुछ कह गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('11b8b7d1-0153-4ae6-9135-1fee33bcc993', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जिन यातनाओं के बीच वह घिरे थे और जिस मनःस्थिति में जी रहे थे, उसमें आँखें ही बहुत कुछ कह देती हैं, मुँह खोलने की ज़रूरत नहीं पड़ती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f4e4adff-b46d-43bb-b9fe-bcce179b1279', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका की जिंदगी से मैं बहुत गहरे में जुड़ा हूँ। अपने गाँव में जिन चंद लोगों को मैं सम्मान देता हूँ, उनमें हरिहर काका भी एक हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4c569512-ec9d-4f35-8898-e0041b6acc15', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के प्रति मेरी आसक्ति के अनेक व्यावहारिक और वैचारिक कारण हैं। उनमें प्रमुख कारण दो हैं। एक तो यह कि हरिहर काका मेरे पड़ोस में रहते हैं और दूसरा कारण यह कि मेरी माँ बताती है, हरिहर काका बचपन में मुझे बहुत दुलार करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('596598a3-8f75-4260-90a5-fb97850cb879', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने कंधे पर बैठाकर घुमाया करते थे। एक पिता अपने बच्चे को जितना प्यार करता है, उससे कहीं ज्यादा प्यार हरिहर काका मुझे करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6a2b0af7-d369-4b75-a080-2d6ff3aee229', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और जब मैं सयाना हुआ तब मेरी पहली दोस्ती हरिहर काका के साथ ही हुई। हरिहर काका ने भी जैसे मुझसे दोस्ती के लिए ही इतनी उम्र तक प्रतीक्षा की थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e5a0ad52-52f1-4768-a62d-28796c090db3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माँ बताती है कि मुझसे पहले गाँव में किसी अन्य से उनकी इतनी गहरी दोस्ती नहीं हुई थी। वह मुझसे कुछ भी नहीं छिपाते थे। खूब खुलकर बातें करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('436b4c66-cc5d-405a-99eb-d31213924435', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन फिलहाल मुझसे भी कुछ कहना उन्होंने बंद कर दिया है। उनकी इस स्थिति ने मुझे चिंतित कर दिया है। जैसे कोई नाव बीच मझधार में फँसी हो और उस पर सवार लोग चिल्लाकर भी अपनी रक्षा न कर सकते हों, क्योंकि उनकी चिल्लाहट दूर तक फैले सागर के बीच उठती-गिरती लहरों में विलीन हो जाने के अतिरिक्त कर ही क्या सकती है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1b538632-b356-4919-9a99-a6d5624f3477', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मौन होकर जल-समाधि लेने के अतिरिक्त कोई दूसरा विकल्प नहीं। लेकिन मन इसे मानने को कतई तैयार नहीं। जीने की लालसा की वजह से बेचैनी और छटपटाहट बढ़ गई हो, कुछ ऐसी ही स्थिति के बीच हरिहर काका घिर गए हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6080f7a9-eaa9-4773-b718-236bd5c32581', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के बारे में मैं सोचता हूँ तो मुझे लगता है कि वह यह समझ नहीं पा रहे हैं कि कहें तो क्या कहें? अब कोई ऐसी बात नहीं जिसे कहकर वह हल्का हो सकें। कोई ऐसी उक्ति नहीं जिसे कहकर वे मुक्ति पा सकें। हरिहर काका की स्थिति में मैं भी होता तो निश्चय ही इस गूंगेपन का शिकार हो जाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cd7ca946-0ca9-4da7-b612-84bd44033729', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका इस स्थिति में कैसे आ फँसे? यह कौन-सी स्थिति है? इसके लिए कौन जिम्मेवार है? यह सब बताने से पहले अपने गाँव का और खासकर अपने गाँव की ठाकुरबारी का संक्षिप्त परिचय मैं आपको दे देना उचित समझता हूँ क्योंकि उसके बिना तो यह कहानी अधूरी ही रह जाएगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('215d6897-26d7-4349-b3ca-cce3fbb1fdf4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा गाँव कस्बाई शहर आरा से चालीस किलोमीटर की दूरी पर है। हसनबाजार बस स्टैंड के पास। गाँव की कुल आबादी ढाई-तीन हजार होगी। गाँव में तीन प्रमुख स्थान हैं। गाँव के पश्चिम किनारे का बड़ा-सा तालाब। गाँव के मध्य स्थित बरगद का पुराना वृक्ष और गाँव के पूरब में ठाकुरजी का विशाल मंदिर, जिसे गाँव के लोग ठाकुरबारी कहते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4fdca074-bbd0-4203-85df-61ed20738ef4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में इस ठाकुरबारी की स्थापना कब हुई, इसकी ठीक-ठीक जानकारी किसी को नहीं। इस संबंध में गाँव में जो कहानी प्रचलित है वह यह कि वर्षों पहले जब यह गाँव पूरी तरह बसा भी नहीं था, कहीं से एक संत आकर इस स्थान पर झोपड़ी बना रहने लगे थे। वह सुबह-शाम यहाँ ठाकुरजी की पूजा करते थे। लोगों से मांगकर खा लेते थे और पूजा-पाठ की भावना जाग्रत करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f47680a5-0597-484d-bf59-d52dc350f4ff', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बाद में लोगों ने चंदा करके यहाँ ठाकुरजी का एक छोटा-सा मंदिर बनवा दिया। फिर जैसे-जैसे गाँव बसता गया और आबादी बढ़ती गई, मंदिर के कलेवर में भी विस्तार होता गया। लोग ठाकुरजी को मन्नौती मनाते कि पुत्र हो, मुकदमे में विजय हो, लड़की की शादी अच्छे घर में तय हो, लड़के को नौकरी मिल जाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ab1a09c7-d359-4843-9bb6-c0d5bbf9edfe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$फिर इसमें जिनको सफलता मिलती, वह खुशी में ठाकुरजी पर रुपये, जेवर, अनाज चढ़ाते। अधिक खुशी होती तो ठाकुरजी के नाम अपने खेत का एक छोटा-सा टुकड़ा लिख देते। यह परंपरा आज तक जारी है। अधिकांश लोगों को विश्वास है कि उन्हें अच्छी फसल होती है तो ठाकुरजी की कृपा से। मुकदमे में उनकी जीत हुई तो ठाकुरजी के चलते। लड़की की शादी इसीलिए जल्दी तय हो गई, क्योंकि ठाकुरजी को मन्नौती मनाई गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9d744450-009c-400b-a757-057a09c5a8f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लोगों के इस विश्वास का ही यह परिणाम है कि गाँव की अन्य चीज़ों की तुलना में ठाकुरबारी का विकास हजार गुना अधिक हुआ है। अब तो यह गाँव ठाकुरबारी से ही पहचाना जाता है। यह ठाकुरबारी न सिर्फ मेरे गाँव की एक बड़ी और विशाल ठाकुरबारी है बल्कि पूरे इलाके में इसकी जोड़ की दूसरी ठाकुरबारी नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('94b28efb-bab4-40a8-b9c0-374b0988a06a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठाकुरबारी के नाम पर बीस बीघे खेत हैं। धार्मिक लोगों की एक समिति है, जो ठाकुरबारी की देखरेख और संचालन के लिए प्रत्येक तीन साल पर एक महंत और एक पुजारी की नियुक्ति करती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('03bd57b5-8c02-4d72-bafd-d41219dc360a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका इस स्थिति में कैसे आ फँसे? यह कौन-सी स्थिति है? इसके लिए कौन जिम्मेवार है? यह सब बताने से पहले अपने गाँव का और खासकर अपने गाँव की ठाकुरबारी का संक्षिप्त परिचय मैं आपको दे देना उचित समझता हूँ क्योंकि उसके बिना तो यह कहानी अधूरी ही रह जाएगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('00ff12de-ba0a-4034-b2f9-86ff467718ea', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में तीन प्रमुख स्थान हैं। गाँव के पश्चिम किनारे का बड़ा-सा तालाब। गाँव के मध्य स्थित बरगद का पुराना वृक्ष और गाँव के पूरब में ठाकुरजी का विशाल मंदिर, जिसे गाँव के लोग ठाकुरबारी कहते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bb17bf03-09c0-4944-a82c-0a91ff6b2a7f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के परिवार के पास कुल साठ बीघे खेत हैं। प्रत्येक भाई के हिस्से पंद्रह बीघे पड़ेंगे। कृषि-कार्य पर ये लोग निर्भर हैं। शायद इसीलिए अब तक संयुक्त परिवार के रूप में ही रहते आ रहे हैं। हरिहर काका के तीनों भाइयों ने अपनी पत्नियों को यह सीख दी थी कि हरिहर काका की अच्छी तरह सेवा करें। समय पर उन्हें नाश्ता-खाना दें। किसी बात की तकलीफ न होने दें। कुछ दिनों तक वे हरिहर काका की खोज-खबर लेती रहीं। फिर उन्हें कौन पूछने वाला? 'ठहर-चौका' लगाकर पंखा झलते हुए अपने मर्दों को अच्छे-अच्छे व्यंजन खिलातीं। हरिहर काका के आगे तो बची-खुची चीजें आतीं। कभी-कभी तो हरिहर काका को रूखा-सूखा खाकर ही संतोष करना पड़ता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c9bec4f9-295a-4b5b-a6ec-3e199f1a6479', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर कभी हरिहर काका की तबीयत खराब हो जाती तो वह मुसीबत में पड़ जाते। इतने बड़े परिवार के रहते हुए भी कोई उन्हें पानी देने वाला तक नहीं। सभी अपने कामों में मशगूल। बच्चे या तो पढ़-लिख रहे होते या धमाचौकड़ी मचाते। मर्द खेतों पर गए रहते। औरतें हाल पूछने भी नहीं आतीं। दालान के कमरे में अकेले पड़े हरिहर काका को स्वयं उठकर अपनी जरूरतों की पूर्ति करनी पड़ती। ऐसे वक्त अपनी पत्नियों को याद कर-करके हरिहर काका की आँखें भर आतीं। भाइयों के परिवार के प्रति मोहभंग की शुरुआत इन्हीं क्षणों में हुई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('be6a7d3c-047b-4838-b8c8-f444259b1457', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और फिर, एक दिन तो विस्फोट ही हो गया। उस दिन हरिहर काका की सहन-शक्ति जवाब दे गई। उस दिन शहर में क्लर्की करने वाले भतीजे का एक दोस्त गाँव आया था। उसी के आगमन के उपलक्ष्य में दो-तीन तरह की सब्जी, बजेके, चटनी, रायता आदि बने थे। बीमारी से उठे हरिहर काका का मन स्वादिष्ट भोजन के लिए बेचैन था। मन ही मन उन्होंने अपने भतीजे के दोस्त की सराहना की, जिसके बहाने उन्हें अच्छी चीजें खाने को मिलने वाली थीं। लेकिन बातें बिलकुल विपरीत हुईं। सबों ने खाना खा लिया, उनको कोई पूछने तक नहीं आया। उनके तीनों भाई खाना खाकर खलिहान में चले गए। दौनी हो रही थी। वे इस बात के प्रति निश्चिंत थे कि हरिहर काका को तो पहले ही खिला दिया गया होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('44042ca6-ca68-49f7-99bc-cd7154f75158', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंत में हरिहर काका ने स्वयं दालान के कमरे से निकल हवेली में प्रवेश किया। तब उनके छोटे भाई की पत्नी ने रूखा-सूखा खाना लाकर उनके सामने परोस दिया— भात, दाल और अचार। बस, हरिहर काका के बदन में तो जैसे आग लग गई। उन्होंने थाली उठाकर बीच आँगन में फेंक दी। झन्न की तेज आवाज के साथ आँगन में थाली गिरी। भात बिखर गया। विभिन्न घरों में बैठी लड़कियाँ, बहुएँ सब एक ही साथ बाहर निकल आईं। हरिहर काका गरजते हुए हवेली से दालान की ओर चल पड़े— 'समझ रही हो कि मुफ्त में खिलाती हो, तो अपने मन से यह बात निकाल देना। मेरे हिस्से के खेत की पैदावार इसी घर में आती है। उसमें तो मैं दो-चार नौकर रख लूँ, आराम से खाऊँ, तब'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7be73667-652e-44e6-8fe9-9c96303d510d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के परिवार के पास कुल साठ बीघे खेत हैं। प्रत्येक भाई के हिस्से पंद्रह बीघे पड़ेंगे। कृषि-कार्य पर ये लोग निर्भर हैं। शायद इसीलिए अब तक संयुक्त परिवार के रूप में ही रहते आ रहे हैं। हरिहर काका के तीनों भाइयों ने अपनी पत्नियों को यह सीख दी थी कि हरिहर काका की अच्छी तरह सेवा करें। समय पर उन्हें नाश्ता-खाना दें। किसी बात की तकलीफ न होने दें।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bdf9a522-e16f-4704-a6c4-8ef89cc3acaf', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कुछ दिनों तक वे हरिहर काका की खोज-खबर लेती रहीं। फिर उन्हें कौन पूछने वाला? 'ठहर-चौका' लगाकर पंखा झलते हुए अपने मर्दों को अच्छे-अच्छे व्यंजन खिलातीं। हरिहर काका के आगे तो बची-खुची चीजें आतीं। कभी-कभी तो हरिहर काका को रूखा-सूखा खाकर ही संतोष करना पड़ता। अगर कभी हरिहर काका की तबीयत खराब हो जाती तो वह मुसीबत में पड़ जाते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bf8236cd-6c76-412a-9f42-507491bfa5db', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इतने बड़े परिवार के रहते हुए भी कोई उन्हें पानी देने वाला तक नहीं। सभी अपने कामों में मशगूल। बच्चे या तो पढ़-लिख रहे होते या धमाचौकड़ी मचाते। मर्द खेतों पर गए रहते। औरतें हाल पूछने भी नहीं आतीं। दालान के कमरे में अकेले पड़े हरिहर काका को स्वयं उठकर अपनी जरूरतों की पूर्ति करनी पड़ती। ऐसे वक्त अपनी पत्नियों को याद कर-करके हरिहर काका की आँखें भर आतीं। भाइयों के परिवार के प्रति मोहभंग की शुरुआत इन्हीं क्षणों में हुई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('444513f6-8272-45e6-bbb5-f8b77a524a4f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और फिर, एक दिन तो विस्फोट ही हो गया। उस दिन हरिहर काका की सहन-शक्ति जवाब दे गई। उस दिन शहर में क्लर्की करने वाले भतीजे का एक दोस्त गाँव आया था। उसी के आगमन के उपलक्ष्य में दो-तीन तरह की सब्जी, बजेके, चटनी, रायता आदि बने थे। बीमारी से उठे हरिहर काका का मन स्वादिष्ट भोजन के लिए बेचैन था। मन ही मन उन्होंने अपने भतीजे के दोस्त की सराहना की, जिसके बहाने उन्हें अच्छी चीजें खाने को मिलने वाली थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('eca75a52-4df0-4af2-8c79-b00ca69b771f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन बातें बिलकुल विपरीत हुईं। सबों ने खाना खा लिया, उनको कोई पूछने तक नहीं आया। उनके तीनों भाई खाना खाकर खलिहान में चले गए। दौनी हो रही थी। वे इस बात के प्रति निश्चिंत थे कि हरिहर काका को तो पहले ही खिला दिया गया होगा। अंत में हरिहर काका ने स्वयं दालान के कमरे से निकल हवेली में प्रवेश किया। तब उनके छोटे भाई की पत्नी ने रूखा-सूखा खाना लाकर उनके सामने परोस दिया— भात, दाल और अचार।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('46168bc0-95a4-4454-83ff-c7cdb14c4dfc', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन हरिहर काका न ^हाँ* कहते और न ^ना*। ^ना* कहकर वे महंत जी को दुखी करना नहीं चाहते थे क्योंकि भाई के परिवार से जो सुख-सुविधाएँ उन्हें मिल रही थीं, वे महंत जी की कृपा से ही। और ^हाँ* तो उन्हें कहना है नहीं, क्योंकि अपनी जिंदगी में अपनी जमीन उन्हें किसी को नहीं लिखनी। इस मुद्दे पर वे जागरूक हो गए थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('03aeff8d-a6a7-463b-a44d-697044a8ac64', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर बीतते समय के अनुसार महंत जी की चिंताएँ बढ़ती जा रही थीं। जाल में फँसी चिड़िया पकड़ से बाहर हो गई थी, महंत जी इस बात को सह नहीं पा रहे थे। महंत जी को लग रहा था कि हरिहर धर्म-संकट में पड़ गया है। एक ओर वह चाहता है कि ठाकुरजी को लिख दूँ, किंतु दूसरी ओर भाई के परिवार के माया-मोह में बँध जाता है। इस स्थिति में हरिहर का अपहरण कर ”जबरदस्ती उससे लिखवाने के अतिरिक्त दूसरा कोई विकल्प नहीं। बाद में हरिहर स्वयं राजी हो जाएगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e9542e87-61fa-4c72-a49e-2da45458227f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महंत जी लड़ाकू और दबंग प्रकृति के आदमी हैं। अपनी योजना को कार्य-रूप में परिणत करने के लिए वह जी-जान से जुट गए। हालाँकि यह सब गोपनीयता का निर्वाह करते हुए ही वह कर रहे थे। हरिहर काका के भाइयों को इसकी भनक तक नहीं थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c9e278f4-c5e2-4fde-9d66-0bbcc20e89eb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बात अभी हाल की ही है। आधी रात के आसपास ठाकुरबारी के साधु-संत और उनके पक्षधर भाला, गँडासा और बंदूक से लैस एकाएक हरिहर काका के दालान पर आ धमके। हरिहर काका के भाई इस अप्रत्याशित हमले के लिए तैयार नहीं थे। इससे पहले कि वे जवाबी कार्रवाई करें और गुहार लगाकर अपने लोगों को जुटाएँ, तब तक आक्रमणकारी उनको पीठ पर लादकर चंपत हो गए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f479fb76-d59b-4203-958a-3be84bfeb1fd', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में किसी ने ऐसी घटना नहीं देखी थी, न सुनी ही थी। सारा गाँव जाग गया। शुभचिंतक तो उनके यहाँ जुटने लगे, लेकिन अन्य लोग अपने दालान और मकान की छतों पर जमा होकर आहट लेने और बातचीत करने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f89ce104-02ba-4df2-acaa-a9b4fd9139cc', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के भाई लोगों के साथ उन्हें ढूँढ़ने निकले। उन्हें लगा कि यह महंत का काम है। वे मय दल-बल ठाकुरबारी जा पहुँचे। वहाँ खामोशी और शांति नजर आई। रोज की भाँति ठाकुरबारी का मुख्य फाटक बंद था। वातावरण में रात का सन्नाटा और सूनापन व्याप्त मिला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4bc7847f-3c04-47e6-93d6-80b0756ccaa2', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्हें लगा, यह काम महंत का नहीं, बाहर के डाकुओं का है। वे तो हरजाने की मोटी रकम लेकर ही हरिहर काका को मुक्त करेंगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ff852392-4237-4979-b65e-42e22906a05f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खोज में निकले लोग किसी दूसरी दिशा की ओर प्रस्थान करते कि इसी समय ठाकुरबारी के अंदर से बातचीत करने की सम्मिलित, किंतु धीमी आवाज सुनाई पड़ी। सबके कान खड़े हो गए। उन्हें यकीन हो गया कि हरिहर काका इसी में हैं। अब क्या सोचना? वे ठाकुरबारी का फाटक पीटने लगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b473bd7f-2482-4fde-a64d-aa2f8e2bbb03', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका न ^हाँ* कहते और न ^ना*। ^ना* कहकर वे महंत जी को दुखी करना नहीं चाहते थे क्योंकि भाई के परिवार से जो सुख-सुविधाएँ उन्हें मिल रही थीं, वे महंत जी की कृपा से ही। और ^हाँ* तो उन्हें कहना है नहीं, क्योंकि अपनी जिंदगी में अपनी जमीन उन्हें किसी को नहीं लिखनी। इस मुद्दे पर वे जागरूक हो गए थे। पर बीतते समय के अनुसार महंत जी की चिंताएँ बढ़ती जा रही थीं। जाल में फँसी चिड़िया पकड़ से बाहर हो गई थी, महंत जी इस बात को सह नहीं पा रहे थे। महंत जी को लग रहा था कि हरिहर धर्म-संकट में पड़ गया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('665c233e-4cb3-4804-bb6c-5851a384cb5a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$महंत जी लड़ाकू और दबंग प्रकृति के आदमी हैं। अपनी योजना को कार्य-रूप में परिणत करने के लिए वह जी-जान से जुट गए। हालाँकि यह सब गोपनीयता का निर्वाह करते हुए ही वह कर रहे थे। हरिहर काका के भाइयों को इसकी भनक तक नहीं थी। बात अभी हाल की ही है। आधी रात के आसपास ठाकुरबारी के साधु-संत और उनके पक्षधर भाला, गँडासा और बंदूक से लैस एकाएक हरिहर काका के दालान पर आ धमके। हरिहर काका के भाई इस अप्रत्याशित हमले के लिए तैयार नहीं थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('21ae862c-5e4b-4828-8348-471beca0b4f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस वर्ग की ओर से हवाई फायरिंग भी किए जा रहे थे, लेकिन ठाकुरबाड़ी की ओर से कोई जवाब नहीं आ रहा था। सुबह तड़के एक वृद्ध साधु ने ठाकुरबाड़ी का फाटक खोल दिया। उस साधु की उम्र अस्सी वर्ष से अधिक की होगी। वह लाठी के सहारे काँपते हुए खड़ा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b4816957-8d9f-441d-b377-11896035cd21', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज ने उस वृद्ध साधु के पास पहुँच हरिहर काका तथा ठाकुरबाड़ी के महंत, पुजारी एवं अन्य साधुओं के बारे में पूछा। लेकिन उसने कुछ भी बताने से इनकार कर दिया। पुलिस इंचार्ज ने कई बार उससे पूछा। डाँट लगाई, धमकियाँ दीं, लेकिन हर बार एक ही वाक्य कहता, 'मुझे कुछ मालूम नहीं।' ऐसे वक्त पुलिस के लोग मार-पीट का सहारा लेकर भी बात उगलवाते हैं; लेकिन उस साधु की वय देखकर पुलिस इंचार्ज को महटिया जाना पड़ा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('0737a8a0-9202-47fa-aebe-14317a78572a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज के नेतृत्व में पुलिस के जवान ठाकुरबाड़ी की तलाशी लेने लगे। लेकिन न तो ठाकुरबाड़ी के नीचे के कमरों में ही कोई पाया गया और न छत के कमरों में ही। पुलिस के जवानों ने खूब छान-बीन की, उस वृद्ध साधु के अलावा कोई दूसरा ठाकुरबाड़ी में नहीं मिला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ad1d68ac-0075-4252-83f8-d13cc3812338', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका के भाई चिंता, परेशानी और दुखद आश्चर्य से घिर गए। ठाकुरबाड़ी के महंत और साधु-संत हरिहर काका को लेकर कहाँ भाग गए? अब क्या होगा? काफी पैसे खर्च कर पुलिस को लाए थे। पुलिस के साथ आने के बाद वह अंदर ही अंदर गर्व महसूस कर रहे थे। उन्हें लग रहा था कि अब भाई को वे आसानी से घर ले जाएंगे तथा साधु-संतों को जेल भिजवा देंगे। लेकिन दोनों में से एक भी नहीं हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f4d13071-2c0f-4f40-b8ad-434194cc0d99', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठाकुरबाड़ी के जो कमरे खुले थे, उनकी तलाशी पहले ली गई थी। बाद में जिन कमरों की चिटकिनी बंद थी, उन्हें भी खोलकर देखा गया था। एक कमरे के बाहर बड़ा-सा ताला लटक रहा था। पुलिस और हरिहर काका के भाई सब वहीं एकत्र हो गए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3d236539-620c-4bd1-a371-6e6289a693f3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस कमरे की कुंजी की माँग वृद्ध साधु से की गई तो उसने साफ कह दिया, 'मेरे पास नहीं।' जब उससे पूछा गया, 'इस कमरे में क्या है?' तब उसने जवाब दिया, 'अनाज है।' पुलिस इंचार्ज अभी यह सोच ही रहे थे कि इस कमरे का ताला तोड़कर देखा जाए या छोड़ दिया जाए कि अचानक उस कमरे के दरवाजे को भीतर से किसी ने धक्का देना शुरू किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('4d6e3979-1927-4549-b1cc-b942cc4314b1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस वर्ग की ओर से हवाई फायरिंग भी किए जा रहे थे, लेकिन ठाकुरबाड़ी की ओर से कोई जवाब नहीं आ रहा था। सुबह तड़के एक वृद्ध साधु ने ठाकुरबाड़ी का फाटक खोल दिया। उस साधु की उम्र अस्सी वर्ष से अधिक की होगी। वह लाठी के सहारे काँपते हुए खड़ा था। पुलिस इंचार्ज ने उस वृद्ध साधु के पास पहुँच हरिहर काका तथा ठाकुरबाड़ी के महंत, पुजारी एवं अन्य साधुओं के बारे में पूछा। लेकिन उसने कुछ भी बताने से इनकार कर दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b25eb603-8882-4275-903d-b8f8c87ee15a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस इंचार्ज ने कई बार उससे पूछा। डाँट लगाई, धमकियाँ दीं, लेकिन हर बार एक ही वाक्य कहता, 'मुझे कुछ मालूम नहीं।' ऐसे वक्त पुलिस के लोग मार-पीट का सहारा लेकर भी बात उगलवाते हैं; लेकिन उस साधु की वय देखकर पुलिस इंचार्ज को महटिया जाना पड़ा। पुलिस इंचार्ज के नेतृत्व में पुलिस के जवान ठाकुरबाड़ी की तलाशी लेने लगे। लेकिन न तो ठाकुरबाड़ी के नीचे के कमरों में ही कोई पाया गया और न छत के कमरों में ही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3ad35934-4e59-4945-89b3-7c67bcf34498', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के जवानों ने खूब छान-बीन की, उस वृद्ध साधु के अलावा कोई दूसरा ठाकुरबाड़ी में नहीं मिला। हरिहर काका के भाई चिंता, परेशानी और दुखद आश्चर्य से घिर गए। ठाकुरबाड़ी के महंत और साधु-संत हरिहर काका को लेकर कहाँ भाग गए? अब क्या होगा? काफी पैसे खर्च कर पुलिस को लाए थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('90ac4b39-d7a4-4cd1-81ee-343828d9e9f3', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के साथ आने के बाद वह अंदर ही अंदर गर्व महसूस कर रहे थे। उन्हें लग रहा था कि अब भाई को वे आसानी से घर ले जाएंगे तथा साधु-संतों को जेल भिजवा देंगे। लेकिन दोनों में से एक भी नहीं हुआ। ठाकुरबाड़ी के जो कमरे खुले थे, उनकी तलाशी पहले ली गई थी। बाद में जिन कमरों की चिटकिनी बंद थी, उन्हें भी खोलकर देखा गया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ffec6179-9f7f-49d0-801c-eedbf00b63e4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक कमरे के बाहर बड़ा-सा ताला लटक रहा था। पुलिस और हरिहर काका के भाई सब वहीं एकत्र हो गए। उस कमरे की कुंजी की माँग वृद्ध साधु से की गई तो उसने साफ कह दिया, 'मेरे पास नहीं।' जब उससे पूछा गया, 'इस कमरे में क्या है?' तब उसने जवाब दिया, 'अनाज है।' पुलिस इंचार्ज अभी यह सोच ही रहे थे कि इस कमरे का ताला तोड़कर देखा जाए या छोड़ दिया जाए कि अचानक उस कमरे के दरवाजे को भीतर से किसी ने धक्का देना शुरू किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('b3f55bda-5d3c-4baf-a0d1-765e13310708', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के जवान सावधान हो गए। ताला तोड़कर कमरे का दरवाजा खोला गया। कमरे के भीतर हरिहर काका जिस स्थिति में मिले, उसे देखकर उनके भाइयों का खून खौल उठा। उस वक्त अगर महंत, पुजारी या अन्य नौजवान साधु उन्हें नजर आ जाते तो वे जीते-जी उन्हें नहीं छोड़ते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5b191511-8b56-408e-8c5f-36f5afdbe13f', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन हरिहर काका सोच कुछ और रहे थे और वातावरण कुछ दूसरा ही तैयार हो रहा था। ठाकुरबारी से जिस दिन उन्हें वापस लाया गया था, उसी दिन से उनके भाई और रिश्ते-नाते के लोग समझाने लगे थे कि विधिवत अपनी जायदाद वे अपने भतीजों के नाम लिख दें। वह जब तक ऐसा नहीं करेंगे तब तक महंत की गिद्ध-दृष्टि उनके ऊपर लगी रहेगी। सिर पर मंडरा रहे तूफान से मुक्ति पाने के लिए उनके समक्ष अब यही एकमात्र रास्ता है---।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1ad8fb8f-dd1e-447c-805e-574591415d33', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुबह, दोपहर, शाम, रात गए तक यही चर्चा। लेकिन हरिहर काका साफ नकार जाते। कहते—'मेरे बाद तो मेरी जायदाद इस परिवार को स्वतः मिल जाएगी इसलिए लिखने का कोई अर्थ नहीं। महंत ने अँगूठे के जो जबरन निशान लिए हैं, उसके खिलाफ मुकदमा हमने किया ही है---।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d086b6a4-474f-4c1e-9d41-6dda1a08af21', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भाई जब समझाते-समझाते हार गए तब उन्होंने डाँटना और दबाव देना शुरू किया। लेकिन काका इस रास्ते भी राजी नहीं हुए। स्पष्ट कह दिया कि अपनी जिंदगी में वह नहीं लिखेंगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d54d4bf5-c48c-44ba-8d0d-6f62d0d998df', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बस, एक रात उनके भाइयों ने वही रूप धारण कर लिया, जो रूप महंत और उनके सहयोगियों ने धारण किया था। हरिहर काका को अपनी आँखों पर विश्वास नहीं हुआ। उनके वही अपने सगे भाई, जो उनकी सेवा और सुरक्षा में तैयार रहते थे, उन्हें अपना अभिन्न समझते थे, जो उनकी नींद ही सोते और जागते थे, हथियार लेकर उनके सामने खड़े थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ec614817-1286-4287-b5bf-e2c0b7d8dd64', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कह रहे थे—'सीधे मन से कागजों पर जहाँ-जहाँ जरूरत है, अँगूठे के निशान बनाते चलो अन्यथा मारकर यहीं घर के अंदर गाड़ देंगे। गाँव के लोगों को कोई सूचना तक नहीं मिल पाएगी।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('b5648240-e163-487c-89c1-3dd12a0f28d8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर पहले वाली बात होती तो हरिहर काका डर जाते। अज्ञान की स्थिति में ही मनुष्य मृत्यु से डरते हैं। ज्ञान होने के बाद तो आदमी आवश्यकता पड़ने पर मृत्यु को वरण करने के लिए तैयार हो जाता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('23c70994-a9ce-441a-ad86-a53b36ca617e', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका ने सोच लिया कि ये सब एक ही बार उन्हें मार दें, वह ठीक होगा; लेकिन अपनी जमीन लिखकर रामेश्वर की विधवा की तरह शेष जिंदगी वे घुट-घुटकर मरें, यह ठीक नहीं होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dd71fa8f-9b38-4477-b4bf-dc1a016726fe', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रामेश्वर की विधवा को बहला-फुसलाकर उसके हिस्से की जमीन रामेश्वर के भाइयों ने लिखवा ली। शुरू में तो उसका खूब आदर-मान किया, लेकिन बुढ़ापे में उसे दोनों जून खाना देते उन्हें अखरने लगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('15c5d7dc-91ca-4ddd-af2b-85e69ee8b8d1', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंत में तो उसकी वह दुर्गति हुई कि गाँव के लोग देखकर सिहर जाते। हरिहर काका को लगता है कि अगर रामेश्वर की विधवा ने अपनी जमीन नहीं लिखी होती तो अंत समय तक लोग उसके पाँव पखारते होते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('231f992a-b73e-442d-83d4-606c1e7e1da5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका गुस्से में खड़े हो गए और गरजते हुए कहा, 'मैं अकेला हूँ---तुम सब इतने हो! ठीक है, मुझे मार दो---मैं मर जाऊँगा, लेकिन जीते-जी एक धूर जमीन भी तुम्हें नहीं लिखूँगा---'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('693ee17d-5f99-4049-abc4-872fb649fde5', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$---तुम सब ठाकुरबारी के महंत-पुजारी से रत्ती भर भी कम नहीं---!'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4f0af26c-052c-4142-9290-692d21aa00d6', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'देखते हैं, कैसे नहीं लिखोगे? लिखना तो तुम्हें है ही, चाहे हँस के लिखो या रो के---।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1157cd4d-e386-42b0-84da-e11d9429b8de', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तब उसी स्थिति में रहकर ही उनके भाइयों और महंत जी ने पैरवी लगा और पैसे खर्च कर उन्हें पूरी सहायता पहुँचाई। यह उनकी सहायता का ही परिणाम गहै कि एक व्यक्ति की सुरक्षा के लिए गाँव में पुलिस के चार जवान तैनात कर दिए गए हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6292157e-4c47-4143-a98c-659ff3180cf4', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जहाँ तक मैं समझता हूँ, फिलहाल हरिहर काका पुलिस की सुरक्षा में रह ज़रूर रहे हैं, लेकिन वास्तविक सुरक्षा ठाकुरबारी और अपने भाइयों की ओर से ही मिल रही है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('886a6894-1bfd-42fb-937d-a6da4e41cecf', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठाकुरबारी के साधु-संत और काका के भाई इस बात के प्रति पूरी तरह सतर्क हैं कि उनमें से कोई या गाँव का कोई अन्य हरिहर काका के साथ ज़ोर-ज़बरदस्ती न करने पाए। साथ ही अपना सद्भाव और मधुर व्यवहार प्रकट कर पुनः उनका ध्यान अपनी ओर खींच लेने के लिए दोनों दल प्रयत्नशील हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cfa83bfe-9e8d-47dd-b3cb-3abf98eb65fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में एक नेता जी हैं, वह न तो कोई नौकरी करते हैं और न खेती-गृहस्थी, फिर भी बारह महीने मौज़ उड़ाते रहते हैं। राजनीति की जादुई छड़ी उनके पास है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c7fd92f8-daf7-46cf-83f1-96fbf778df3a', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनका ध्यान हरिहर काका की ओर जाता है। वह तत्काल गाँव के कुछ विशिष्ट लोगों के साथ उनके पास पहुँचते हैं और यह प्रस्ताव रखते हैं कि उनकी ज़मीन में 'हरिहर उच्च विद्यालय' नाम से एक हाई स्कूल खोला जाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('af824e5c-dc89-412c-803d-a8f3c06a41f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इससे उनका नाम अमर हो जाएगा। उनकी ज़मीन का सही उपयोग होगा और गाँव के विकास के लिए एक स्कूल मिल जाएगा। लेकिन हरिहर काका के ऊपर तो अब कोई भी दूसरा रंग चढ़ने वाला नहीं था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('18369d9a-0613-4bfd-8355-85cd546cbbbb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नेता जी भी निराश होकर लौट आते हैं। इन दिनों गाँव की चर्चाओं के केंद्र हैं हरिहर काका। आँगन, खेत, खलिहान, अलाव, बगीचे, बरगद हर जगह उनकी ही चर्चा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('24758fe8-8e8d-4ace-9b97-fd017112ea09', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी घटना की तरह विचारणीय और चर्चनीय कोई दूसरी घटना नहीं। गाँव में आए दिन छोटी-बड़ी घटनाएँ घटती रहती हैं, लेकिन काका के प्रसंग के सामने उनका कोई अस्तित्व नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c720dd47-38b3-4cf3-a6dc-b4aff027e4a7', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गाँव में जहाँ कहीं और जिन लोगों के बीच हरिहर काका की चर्चा छिड़ती है तो फिर उसका कोई अंत नहीं। लोग तरह-तरह की संभावनाएँ व्यक्त करते हैं—'राम जाने क्या होगा?'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('552bc14f-8b5a-414d-81ba-a8d6c551c439', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दोनों ओर के लोगों ने अँगूठे के निशान ले लिए हैं। लेकिन हरिहर ने अपना बयान दर्ज कराया है कि वे दोनों लोगों में से किसी को अपनी ज़मीन का उत्तराधिकारी नहीं मानते हैं। दोनों ओर के लोगों ने ज़बरन उनके अँगूठे के निशान लिए हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4ceab42d-9b70-4d05-a45c-4f8dbfde9b08', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस स्थिति में उनके बाद उनकी जायदाद का हक़दार कौन होगा?' लोगों के बीच बहस छिड़ जाती है। उत्तराधिकारी के कानून पर जो जितना जानता है, उससे दस गुना अधिक उगल देता है। फिर भी कोई समाधान नहीं निकलता। रहस्य खत्म नहीं होता, आशंकाएँ बनी ही रहती हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4ab400d0-9980-4e64-bdf3-f50a5cd9d3eb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन लोग आशंकाओं को नज़रअंदाज़ कर अपनी पक्षधरता शुरू कर देते हैं कि उत्तराधिकार ठाकुरबारी को मिलता तो ठीक रहता। दूसरी ओर के लोग कहते कि हरिहर के भाइयों को मिलता तो ज़्यादा अच्छा रहता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6d5c8ef9-e534-4187-937b-fa7d2c892f25', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पुलिस के जवान हरिहर काका के खर्चे पर ही खूब मौज-मस्ती से रह रहे हैं। जिसका धन वह रहे उपास, खाने वाले करें विलास। अब तक जो नहीं खाया था, दोनों जून उसका भोग लगा रहे हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ddb67d04-7552-48a2-9d9d-6094f8bcab0d', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका को महंत और अपने भाई एक ही श्रेणी के क्यों लगने लगे? क्योंकि दोनों ही उनकी संपत्ति पर नजर रखे हुए थे और उन्हें अपने स्वार्थ के लिए इस्तेमाल करना चाहते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a0900dd3-768d-4f90-bcc4-557d10ae89fb', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ठाकुरबारी के प्रति गाँव वालों के मन में अपार श्रद्धा के जो भाव हैं उससे उनकी धार्मिक अंधविश्वास और रूढ़िवादी मनोवृत्ति का पता चलता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('bcce5764-82ed-4861-a586-57ff2917a432', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अनपढ़ होते हुए भी हरिहर काका दुनिया की बेहतर समझ रखते हैं। उन्होंने संपत्ति के लालच और रिश्तों की खोखली सच्चाई को पहचान लिया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('dd4f08dd-6b37-4b5e-babe-49194744ac91', '8af718c6-ca11-482b-9d6b-832f2b767928', '7da5645d-0dca-4653-9e93-cc3c50ad43dc', 'b3652e7a-8fac-4b16-82c8-595fb1328c1d', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हरिहर काका को जबरन उठा ले जाने वाले ठाकुरबारी के लोग थे। उन्होंने हरिहर काका के साथ बहुत बुरा बर्ताव किया, उन्हें मारा-पीटा और संपत्ति अपने नाम कराने का दबाव डाला।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T06-13-26-102Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
